package live.linghe.privateinput;

import android.content.Context;import java.io.*;import java.math.BigInteger;import java.util.*;import java.util.function.BooleanSupplier;import org.json.*;

/** Authenticated opt-in recency lane; a missing endpoint never disables existing v1 sync. */
final class RecentLearningSync {
 interface Transport{JSONObject post(String path,JSONObject request)throws Exception;}
 interface Save{void run()throws Exception;}
 private final Context context;private final JSONObject state,membership,identity;private final RecentLearningStore store;private final Transport transport;private final BooleanSupplier consent;private final Save save;
 private final String group,sender,binding;private final BigInteger epoch,revision;private final RecentLearningExchangeState exchange;
 RecentLearningSync(Context context,JSONObject state,Transport transport,BooleanSupplier consent,Save save)throws Exception{
  this.context=context;this.state=state;this.transport=transport;this.consent=consent;this.save=save;membership=state.getJSONObject("membership");identity=state.getJSONObject("identity");group=SyncCrypto.id(membership.getString("group"));sender=SyncCrypto.id(identity.getString("device"));epoch=SyncCrypto.u(membership,"epoch");revision=SyncCrypto.u(membership,"revision");binding=group+"/"+epoch+"/"+revision;store=new RecentLearningStore(context.getFilesDir());
  exchange=new RecentLearningExchangeState(binding+"/"+state.optString("endpoint")+"/"+PersonalReset.generation(context));JSONObject cached=state.optJSONObject("recencyExchangeV1");
  if(cached!=null&&cached.optInt("version",0)==1&&exchange.binding.equals(cached.optString("binding")))try{
   exchange.conditional=cached.optBoolean("conditional",false);Map<String,String> known=new TreeMap<>();JSONObject rows=cached.optJSONObject("known");if(rows!=null){Iterator<String> keys=rows.keys();while(keys.hasNext()){String peer=keys.next();known.put(peer,rows.getString(peer));}}exchange.restoreKnown(known);
   exchange.attemptMs=cached.optLong("attemptMs",-1);exchange.successMs=cached.optLong("successMs",-1);exchange.attemptBoot=cached.optString("attemptBoot");exchange.successBoot=cached.optString("successBoot");exchange.attemptSucceeded=cached.optBoolean("attemptSucceeded",false);
  }catch(Exception invalidHint){exchange.conditional=false;exchange.known.clear();exchange.attemptMs=exchange.successMs=-1;exchange.attemptBoot=exchange.successBoot="";exchange.attemptSucceeded=false;}
  // Hints describe durable local merges, never merely received envelopes.
  if(!new File(context.getFilesDir(),"recent-learning-v2.json").isFile()||!new File(context.getFilesDir(),"Shared/learning-v1.json").isFile()){exchange.known.clear();exchange.successMs=-1;exchange.successBoot="";}
 }
 private void persistExchange()throws Exception{
  JSONObject known=new JSONObject();for(Map.Entry<String,String> item:exchange.known.entrySet())known.put(item.getKey(),item.getValue());
  JSONObject next=new JSONObject().put("version",1).put("binding",exchange.binding).put("conditional",exchange.conditional).put("known",known).put("attemptMs",exchange.attemptMs).put("successMs",exchange.successMs).put("attemptBoot",exchange.attemptBoot).put("successBoot",exchange.successBoot).put("attemptSucceeded",exchange.attemptSucceeded);
  boolean existed=state.has("recencyExchangeV1");Object previous=state.opt("recencyExchangeV1");state.put("recencyExchangeV1",next);
  try{allowed();save.run();}catch(Exception failed){if(existed)state.put("recencyExchangeV1",previous);else state.remove("recencyExchangeV1");throw failed;}
 }
 private void mergeAndRemember(JSONObject envelope,long serverNow)throws Exception{
  exchange.merged(envelope.getString("sender"),envelope.getString("event"),()->mergeEnvelope(envelope,serverNow));persistExchange();
 }
 private JSONObject knownSnapshots()throws Exception{JSONObject result=new JSONObject();if(exchange.conditional)for(Map.Entry<String,String> row:exchange.known.entrySet())result.put(row.getKey(),row.getValue());return result;}
 private void allowed()throws Exception{SyncCrypto.require(consent.getAsBoolean()&&(SyncCrypto.find(membership,sender).getInt("permissions")&1)!=0&&SyncCrypto.id(state.getJSONObject("membership").getString("group")).equals(group)&&SyncCrypto.u(state.getJSONObject("membership"),"epoch").equals(epoch)&&SyncCrypto.u(state.getJSONObject("membership"),"revision").equals(revision)&&exchange.binding.equals(binding+"/"+state.optString("endpoint")+"/"+PersonalReset.generation(context)));}
 private JSONObject call(int op,JSONObject body)throws Exception{
  allowed();byte[] encoded=SyncCrypto.bytes(LosslessJson.canonical(body));String nonce=SyncCrypto.id();long now=System.currentTimeMillis()/1000;JSONObject request=new JSONObject().put("version",1).put("group",group).put("sender",sender).put("nonce",nonce).put("issuedAt",now).put("operation",op).put("body",SyncCrypto.b64(encoded));request.put("signature",SyncCrypto.b64(SyncCrypto.sign(RecentLearningWire.request(group,sender,nonce,BigInteger.valueOf(now),op,encoded),SyncCrypto.privateKey("Ed25519",identity.getString("signing")))));
  RecentLearningStore.Usage start=RecentLearningStore.usage(context);JSONObject result=transport.post("/v1/groups/"+group+"/recency",request);RecentLearningStore.Usage end=RecentLearningStore.usage(context);allowed();
  SyncCrypto.require(SyncCrypto.u(result,"version").equals(BigInteger.ONE)&&SyncCrypto.id(result.getString("group")).equals(group)&&SyncCrypto.id(result.getString("sender")).equals(sender)&&SyncCrypto.id(result.getString("nonce")).equals(nonce)&&SyncCrypto.u(result,"epoch").equals(epoch)&&SyncCrypto.u(result,"membershipRevision").equals(revision)&&result.get("ready") instanceof Boolean&&start.bootSession.equals(end.bootSession)&&end.uptime>=start.uptime&&end.uptime-start.uptime<=10);
  double server=SyncCrypto.u(result,"serverTime").doubleValue();int day=SyncCrypto.u(result,"referenceDay").intValueExact();SyncCrypto.require(server<=259200000000.0&&Math.abs(server-now)<300&&Math.floor(server/86400)==day);JSONArray missing=result.getJSONArray("missing");SyncCrypto.require(missing.length()<=64&&(!result.getBoolean("ready")||missing.length()==0));Set<String> seen=new HashSet<>();for(int i=0;i<missing.length();i++){String member=SyncCrypto.id(missing.getString(i));SyncCrypto.find(membership,member);SyncCrypto.require(seen.add(member));}
  store.acceptAuthenticatedPolicy(new RecentLearningStore.PolicyState(binding,new RecentLearning.Policy(day),new RecentLearning.Clock(server,end.uptime,end.bootSession),result.getBoolean("ready")));return result;
 }
 private JSONObject body()throws Exception{return new JSONObject().put("epoch",epoch).put("membershipRevision",revision);}
 private static byte[] header(JSONObject wire)throws Exception{SyncCrypto.require(SyncCrypto.u(wire,"version").equals(BigInteger.ONE));return RecentLearningWire.header(wire.getString("group"),wire.getString("sender"),wire.getString("event"),SyncCrypto.u(wire,"epoch"),SyncCrypto.u(wire,"issuedAt"),SyncCrypto.u(wire,"expiresAt"));}
 private byte[] key(JSONObject wire)throws Exception{JSONObject member=SyncCrypto.find(membership,wire.getString("sender"));SyncCrypto.require((member.getInt("permissions")&1)!=0&&SyncCrypto.id(wire.getString("group")).equals(group)&&SyncCrypto.u(wire,"epoch").equals(epoch));byte[] master=SyncCrypto.data(state,"groupKey");SyncCrypto.require(master.length==32);return SyncCrypto.hkdf(master,RecentLearningWire.salt(group,epoch),RecentLearningWire.info(wire.getString("sender"),SyncCrypto.data(member,"signingPublic")));}
 private JSONObject seal(String payload,long serverNow)throws Exception{byte[] bytes=SyncCrypto.bytes(payload);SyncCrypto.require(bytes.length<=RecentLearningStore.MAX_BYTES);JSONObject wire=new JSONObject().put("version",1).put("group",group).put("sender",sender).put("event",SyncCrypto.id()).put("epoch",epoch).put("issuedAt",serverNow).put("expiresAt",serverNow+7*86400);byte[] header=header(wire),nonce=SyncCrypto.random(12),sealed=SyncCrypto.concat(nonce,SyncCrypto.chacha(true,key(wire),nonce,header,bytes));return wire.put("sealed",SyncCrypto.b64(sealed)).put("signature",SyncCrypto.b64(SyncCrypto.sign(SyncCrypto.concat(header,sealed),SyncCrypto.privateKey("Ed25519",identity.getString("signing")))));}
 private String open(JSONObject wire,long serverNow)throws Exception{byte[] header=header(wire),sealed=SyncCrypto.data(wire,"sealed");SyncCrypto.require(sealed.length>=28&&sealed.length<=RecentLearningStore.MAX_BYTES+28&&SyncCrypto.u(wire,"issuedAt").compareTo(BigInteger.valueOf(serverNow+300))<=0&&SyncCrypto.u(wire,"expiresAt").compareTo(BigInteger.valueOf(serverNow))>0);byte[] key=key(wire);SyncCrypto.verify(SyncCrypto.concat(header,sealed),SyncCrypto.data(wire,"signature"),SyncCrypto.data(SyncCrypto.find(membership,wire.getString("sender")),"signingPublic"));return SyncCrypto.utf8(SyncCrypto.chacha(false,key,Arrays.copyOfRange(sealed,0,12),header,Arrays.copyOfRange(sealed,12,sealed.length)));}
 private void remember(JSONObject wire,long serverNow)throws Exception{store.acceptReceipt(binding,SyncCrypto.id(wire.getString("event")),SyncCrypto.b64(SyncCrypto.sha(SyncCrypto.concat(header(wire),SyncCrypto.data(wire,"sealed")))),SyncCrypto.u(wire,"expiresAt").longValueExact(),serverNow);}
 private void mergeEnvelope(JSONObject envelope,long serverNow)throws Exception{String incoming=open(envelope,serverNow);allowed();remember(envelope,serverNow);RecentLearningStore.Snapshot merged=store.mergeAuthenticatedArchive(incoming,binding);allowed();String projection=RecentLearningStore.legacyProjection(merged);new LearningSnapshotFile(new File(context.getFilesDir(),"Shared")).publish(projection);if(merged.personal!=null)new PersonalLexicon(new File(context.getFilesDir(),"Shared")).mergeSynchronized(merged.personal.synchronizationObject().toString());}
 private void markPublication(String digest,long time)throws Exception{boolean hadDigest=state.has("recencyPublishedDigest"),hadTime=state.has("recencyPublishedAt");Object oldDigest=state.opt("recencyPublishedDigest"),oldTime=state.opt("recencyPublishedAt");state.put("recencyPublishedDigest",digest).put("recencyPublishedAt",time);try{save.run();}catch(Exception failure){if(hadDigest)state.put("recencyPublishedDigest",oldDigest);else state.remove("recencyPublishedDigest");if(hadTime)state.put("recencyPublishedAt",oldTime);else state.remove("recencyPublishedAt");throw failure;}}
 void synchronize()throws Exception{synchronize(false);}
 void synchronize(boolean explicit)throws Exception{
  RecentLearningStore.Usage began=RecentLearningStore.usage(context);long uptime=Math.round(began.uptime*1000);
  // The latest-slot protocol always carries a COMPLETE archive. Migrated
  // cloud devices maintain that compatibility lane once per independent day.
  // Never turn it into a partial snapshot or use the cloud success timestamp.
  String cloudScope=null;try{cloudScope=new CloudLearningStore(context).compatibilityScope(state);}catch(Exception invalidCloud){cloudScope=null;}
  RecentCompatibilityCadence compatibility=cloudScope==null?null:new RecentCompatibilityCadence(cloudScope);
  if(compatibility!=null){JSONObject saved=state.optJSONObject("recencyCompatibilityV1");if(saved!=null&&saved.optInt("version")==1&&cloudScope.equals(saved.optString("binding"))){compatibility.successWall=saved.optLong("successWall",-1);compatibility.successUptime=saved.optLong("successUptime",-1);compatibility.successBoot=saved.optString("successBoot","");}if(!compatibility.due(Math.round(began.wallSeconds*1000),uptime,began.bootSession))return;}
  if(!exchange.due(uptime,began.bootSession,explicit))return;
  allowed();exchange.attempted(uptime,began.bootSession);persistExchange();
  try{
   JSONObject greeting=body().put("roles",new JSONArray().put("app").put("keyboard"));String knownOwn=exchange.knownEvent(sender);
   if(knownOwn!=null)greeting.put("knownEvent",knownOwn);
   JSONObject hello;
   try{hello=call(1,greeting);}catch(SyncClient.HTTPFailure incompatible){if(knownOwn==null||(incompatible.status!=400&&incompatible.status!=422))throw incompatible;greeting.remove("knownEvent");hello=call(1,greeting);knownOwn=null;}
   exchange.conditional=hello.opt("conditionalSnapshots") instanceof Boolean&&hello.getBoolean("conditionalSnapshots");persistExchange();if(!hello.getBoolean("ready"))return;
   LearningCoordinator coordinator=new LearningCoordinator(context.getFilesDir(),new File(context.getFilesDir(),"Shared"));if(coordinator.requiresPrivateRecovery())return;
   long serverNow=SyncCrypto.u(hello,"serverTime").longValueExact();SyncCrypto.require(hello.has("envelope"));JSONObject own=hello.isNull("envelope")?null:hello.getJSONObject("envelope");RecentLearningSlot slot=new RecentLearningSlot(hello.getString("publishedEvent"),own==null?null:own.getString("event"),sender,own==null?null:own.getString("sender"),exchange.conditional?knownOwn:null);if(own!=null)mergeAndRemember(own,serverNow);
   String legacy=new LearningSnapshotFile(new File(context.getFilesDir(),"Shared")).read();if(legacy!=null)store.mergeLegacy(legacy);String archive=store.outbound(binding),digest=binding+"/"+SyncCrypto.b64(SyncCrypto.sha(SyncCrypto.bytes(archive)));
   long published=state.optLong("recencyPublishedAt",0);if(slot.shouldPush(digest,state.optString("recencyPublishedDigest"),published,serverNow)){JSONObject envelope=seal(archive,serverNow);JSONObject pushed=call(2,body().put("expectedEvent",slot.publishedEvent).put("envelope",envelope));SyncCrypto.require(pushed.getBoolean("ready")&&pushed.get("accepted") instanceof Boolean&&pushed.getBoolean("accepted")&&slot.accepted(pushed.getString("event"),envelope.getString("event"))&&slot.accepted(pushed.getString("publishedEvent"),envelope.getString("event")));allowed();markPublication(digest,SyncCrypto.u(pushed,"serverTime").longValueExact());mergeAndRemember(envelope,SyncCrypto.u(pushed,"serverTime").longValueExact());}
   String after="";Set<String> seen=new HashSet<>();boolean drained=false;
   for(int i=0;i<64;i++){JSONObject request=body().put("after",after);if(exchange.conditional)request.put("knownSnapshots",knownSnapshots());JSONObject pulled=call(3,request);if(!pulled.getBoolean("ready"))return;String next=pulled.getString("next");if(pulled.has("envelope")&&!pulled.isNull("envelope")){JSONObject envelope=pulled.getJSONObject("envelope");String peer=SyncCrypto.id(envelope.getString("sender"));SyncCrypto.require(!peer.equals(sender)&&!next.isEmpty()&&SyncCrypto.id(next).equals(peer)&&seen.add(peer)&&(after.isEmpty()||peer.compareToIgnoreCase(after)>0));mergeAndRemember(envelope,SyncCrypto.u(pulled,"serverTime").longValueExact());}
    else SyncCrypto.require(next.isEmpty());if(next.isEmpty()){drained=true;break;}after=SyncCrypto.id(next);
   }
   SyncCrypto.require(drained);RecentLearningStore.Usage completed=RecentLearningStore.usage(context);exchange.succeeded(Math.round(completed.uptime*1000),completed.bootSession);persistExchange();
   if(compatibility!=null){allowed();String currentScope=new CloudLearningStore(context).compatibilityScope(state);if(compatibility.binding.equals(currentScope)){compatibility.succeeded(Math.round(completed.wallSeconds*1000),Math.round(completed.uptime*1000),completed.bootSession);JSONObject previous=state.optJSONObject("recencyCompatibilityV1");state.put("recencyCompatibilityV1",new JSONObject().put("version",1).put("binding",compatibility.binding).put("successWall",compatibility.successWall).put("successUptime",compatibility.successUptime).put("successBoot",compatibility.successBoot));try{save.run();}catch(Exception failed){if(previous==null)state.remove("recencyCompatibilityV1");else state.put("recencyCompatibilityV1",previous);throw failed;}}}
  }catch(Exception unavailable){store.suspendPolicy();throw unavailable;}finally{PersonalChangeSignal.notifyChanged(context);}
 }
}
